	/* @Override */
	public bool removeVertex(V v) {
		bool removed = base.removeVertex(v);
		maybePerformRemove(() => completeGraph.removeVertex(v));
		return removed;
	}

	/* @Override */
	public void removeVertices(Iterable<V> verticesToRemove) {
		List<E> edgesToRemove = new();
		List<V> removed = new();
		foreach (V v in verticesToRemove) {

			if (base.containsVertex(v)) {
				edgesToRemove.addAll(getIncidentEdges(v));
				removed.add(v);
				base.removeVertex(v);
			}
		}

		maybePerformRemove(() => {
			completeGraph.removeVertices(verticesToRemove);
			completeGraph.removeEdges(edgesToRemove);
		});

		verticesRemoved(removed);
	}

	/* @Override */
	public bool removeEdge(E e) {
		bool removed = base.removeEdge(e);

		List<E> asList = Arrays.asList(e);
		if (removed) {
			fireEdgesRemoved(asList);
		}

		maybePerformRemove(() => completeGraph.removeEdge(e));

		return removed;
	}

	/* @Override */
	public void removeEdges(Iterable<E> toRemove) {
		toRemove.forEach(e => base.removeEdge(e));

		base.removeEdges(toRemove);

		maybePerformRemove(() => {
			completeGraph.removeEdges(toRemove);
		});

		fireEdgesRemoved(toRemove);
	}

	/* @Override */
	public bool addVertex(V v) {
		maybePerformAdd(() => base.addVertex(v));
		return completeGraph.addVertex(v);
	}

	/* @Override */
	public void addEdge(E e) {
		maybePerformAdd(() => base.addEdge(e));
		completeGraph.addEdge(e);
	}

	/* @Override */
	public bool addEdge(E e, Pair<V> endpoints, EdgeType type) {
		maybePerformAdd(() => base.addEdge(e, endpoints, type));
		return completeGraph.addEdge(e, endpoints, type);
	}

	/* @Override */
	public bool addEdge(E e, Collection<V> edgeVertices) {
		maybePerformAdd(() => base.addEdge(e, edgeVertices));
		return completeGraph.addEdge(e, edgeVertices);
	}

	/* @Override */
	public bool addEdge(E e, Collection<V> edgeVertices, EdgeType type) {
		maybePerformAdd(() => base.addEdge(e, edgeVertices, type));
		return completeGraph.addEdge(e, edgeVertices, type);
	}

	/* @Override */
	public bool addEdge(E e, V v1, V v2) {
		maybePerformAdd(() => base.addEdge(e, v1, v2));
		return completeGraph.addEdge(e, v1, v2);
	}

	/* @Override */
	public bool addEdge(E e, V v1, V v2, EdgeType edgeType) {
		maybePerformAdd(() => base.addEdge(e, v1, v2, edgeType));
		return completeGraph.addEdge(e, v1, v2, edgeType);
	}

	/* @Override */
	public bool addEdge(E e, Pair<V> endpoints) {
		maybePerformAdd(() => base.addEdge(e, endpoints));
		return completeGraph.addEdge(e, endpoints);
	}

	/* @Override */
	public void dispose() {
		completeGraph.dispose();
		vertices.clear();
		edges.clear();
	}

