	private class UnfilteredGraph : DefaultVisualGraph<V, E> {

		/* @Override */
		public VisualGraphLayout<V, E> getLayout() {
			// stub
			return null;
		}

		/* @Override */
		public UnfilteredGraph copy() {
			UnfilteredGraph newGraph = new UnfilteredGraph();
			newGraph.vertices.putAll(vertices);
			newGraph.edges.putAll(edges);
			return newGraph;
		}

		/* @Override */
		public void dispose() {
			vertices.clear();
			edges.clear();
		}
	}
